    }$done=true;
}
function sf_media_ini_bytes(string $value): int {$value=trim($value);if($value==='')return 0;$n=(float)$value;$u=strtolower(substr($value,-1));return (int)round($n*($u==='g'?1073741824:($u==='m'?1048576:($u==='k'?1024:1))));}
function sf_media_capabilities(): array {$upload=sf_media_ini_bytes((string)ini_get('upload_max_filesize'));$post=sf_media_ini_bytes((string)ini_get('post_max_size'));$effective=min(array_filter([$upload,$post,1073741824],fn($x)=>$x>0)?:[1073741824]);return ['ffprobe'=>sf_media_ffprobe_path()!=='','gd'=>extension_loaded('gd'),'upload_max_bytes'=>$effective,'upload_max_label'=>round($effective/1048576,1).' MB','audio_fallbacks'=>['wav_riff'=>true,'mp3_frame_id3'=>true]];}
function sf_media_allowed(): array {
    return [
      'audio'=>['audio/mpeg'=>['mp3'],'audio/mp3'=>['mp3'],'audio/wav'=>['wav'],'audio/x-wav'=>['wav'],'audio/wave'=>['wav'],'audio/vnd.wave'=>['wav']],
      'image'=>['image/jpeg'=>['jpg','jpeg'],'image/png'=>['png'],'image/webp'=>['webp'],'image/gif'=>['gif']],
      'video'=>['video/mp4'=>['mp4'],'video/webm'=>['webm'],'video/quicktime'=>['mov']],
      'document'=>['application/pdf'=>['pdf'],'text/plain'=>['txt'],'text/markdown'=>['md'],'application/rtf'=>['rtf']]
