}
function sf_media_detect_type(string $tmp,string $name): array {
    $ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$mime='';
    if(class_exists('finfo')){$fi=new finfo(FILEINFO_MIME_TYPE);$mime=(string)$fi->file($tmp);}elseif(function_exists('mime_content_type'))$mime=(string)@mime_content_type($tmp);
    foreach(sf_media_allowed() as $cat=>$map)foreach($map as $m=>$exts)if($mime===$m&&in_array($ext,$exts,true))return ['category'=>$cat,'mime'=>$mime,'extension'=>$ext==='jpeg'?'jpg':$ext];
    $head=(string)@file_get_contents($tmp,false,null,0,16);
    if($ext==='wav'&&strlen($head)>=12&&substr($head,0,4)==='RIFF'&&substr($head,8,4)==='WAVE')return ['category'=>'audio','mime'=>'audio/wav','extension'=>'wav'];
    if($ext==='mp3'&&(substr($head,0,3)==='ID3'||(strlen($head)>=2&&ord($head[0])===0xFF&&(ord($head[1])&0xE0)===0xE0)))return ['category'=>'audio','mime'=>'audio/mpeg','extension'=>'mp3'];
    if($ext==='pdf'&&substr($head,0,4)==='%PDF')return ['category'=>'document','mime'=>'application/pdf','extension'=>'pdf'];
    throw new InvalidArgumentException('Unsupported media type or file signature. Allowed: MP3, WAV, JPG, PNG, WebP, GIF, MP4, WebM, MOV, PDF, TXT, MD, RTF.');
}
function sf_media_shell_available(string $fn='shell_exec'): bool {
