function sf_media_backfill_catalog(): array {
    sf_media_ensure_schema();$catalog=sf_catalog();$index=[];$indexPath=SF_ROOT.'/storage/media/index.json';if(is_file($indexPath)){$j=json_decode((string)file_get_contents($indexPath),true);if(is_array($j))$index=(array)($j['files']??[]);}$counts=['tracks'=>0,'audio'=>0,'artwork'=>0,'archive'=>0,'skipped'=>0];
    foreach($catalog as $t){$trackId=sf_clean_text($t['id']??'',160);if($trackId==='')continue;$counts['tracks']++;$source=(array)($t['metadata']['source']??[]);
      foreach([['master_sha256','master_audio',false],['preview_sha256','primary_audio',true]] as [$key,$role,$public]){$hash=(string)($source[$key]??'');$row=$hash!==''?($index[$hash]??null):null;if(is_array($row)&&!empty($row['stored_path'])){try{$a=sf_media_register_existing_file((string)$row['stored_path'],basename((string)$row['stored_path']),0);sf_media_attach((int)$a['id'],'track',$trackId,$role,['public_visible'=>$public,'download_allowed'=>false]);$counts['audio']++;}catch(Throwable $e){$counts['skipped']++;}}}
      $hasPreview=(string)($source['preview_sha256']??'')!=='';if(!$hasPreview){$audio=(string)($t['audio']??'');if($audio!==''&&!preg_match('#^(?:https?:)?//#i',$audio)&&!str_starts_with($audio,'api/')){try{$a=sf_media_register_local_copy(SF_ROOT.'/'.ltrim($audio,'/'),basename($audio),0);sf_media_attach((int)$a['id'],'track',$trackId,'primary_audio',['public_visible'=>true,'download_allowed'=>false]);$counts['audio']++;}catch(Throwable $e){$counts['skipped']++;}}}
      $art=(string)($t['artwork']??'');if($art!==''&&!preg_match('#^(?:https?:)?//#i',$art)&&!str_starts_with($art,'api/')){try{$a=sf_media_register_local_copy(SF_ROOT.'/'.ltrim($art,'/'),basename($art),0);sf_media_attach((int)$a['id'],'track',$trackId,'primary_artwork',['public_visible'=>true,'featured'=>true]);$counts['artwork']++;}catch(Throwable $e){$counts['skipped']++;}}
      foreach((array)($t['archive']['media']??[]) as $m){$url=(string)($m['url']??'');if($url===''||preg_match('#^(?:https?:)?//#i',$url)||str_starts_with($url,'api/'))continue;try{$a=sf_media_register_local_copy(SF_ROOT.'/'.ltrim($url,'/'),basename($url),0);sf_media_attach((int)$a['id'],'track',$trackId,'archive',['public_visible'=>true,'download_allowed'=>false,'link'=>['legacy_title'=>$m['title']??'','legacy_caption'=>$m['caption']??'']]);$counts['archive']++;}catch(Throwable $e){$counts['skipped']++;}}
    }return $counts;
}
function sf_media_ingest_upload(array $file,int $adminId): array {
    sf_media_ensure_schema();if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Upload failed with PHP code '.(int)($file['error']??-1).'.');$tmp=(string)($file['tmp_name']??'');if(!is_uploaded_file($tmp))throw new RuntimeException('Invalid uploaded file.');$size=(int)($file['size']??0);if($size<=0)throw new InvalidArgumentException('The uploaded file is empty.');if($size>1024*1024*1024)throw new InvalidArgumentException('Media file exceeds the 1 GB application limit.');
    $type=sf_media_detect_type($tmp,(string)($file['name']??'media'));$sha=hash_file('sha256',$tmp);if(!$sha)throw new RuntimeException('Could not hash uploaded file.');$q=sf_db()->prepare('SELECT id FROM media_assets WHERE sha256=? AND size_bytes=? LIMIT 1');$q->execute([$sha,$size]);$existing=(int)($q->fetchColumn()?:0);if($existing)return sf_media_asset($existing)?:[];
    $uuid=sf_media_uuid();$ext=sf_media_safe_ext($type['extension']);$dir='storage/media/library/'.$type['category'].'/'.substr($sha,0,2);$absDir=SF_ROOT.'/'.$dir;if(!is_dir($absDir)&&!mkdir($absDir,0770,true)&&!is_dir($absDir))throw new RuntimeException('Could not create media storage.');$rel=$dir.'/'.$uuid.'.'.$ext;$abs=SF_ROOT.'/'.$rel;if(!move_uploaded_file($tmp,$abs))throw new RuntimeException('Could not store uploaded media.');
    try{$a=sf_media_analyze($abs,$type['category'],$ext);$tags=(array)($a['technical']['normalized_tags']??[]);$title=sf_clean_text($tags['title']??pathinfo((string)$file['name'],PATHINFO_FILENAME),255);$now=gmdate('c');$q=sf_db()->prepare('INSERT INTO media_assets(uuid,category,mime_type,extension,original_name,stored_path,sha256,size_bytes,width,height,duration_seconds,bitrate_bps,sample_rate_hz,channels,bits_per_sample,codec,title,caption,alt_text,credit,copyright_text,technical_json,variants_json,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$uuid,$type['category'],$type['mime'],$ext,sf_clean_text($file['name']??'media',255),$rel,$sha,$size,(int)$a['width'],(int)$a['height'],round((float)$a['duration'],3),(int)$a['bitrate'],(int)$a['sample_rate'],(int)$a['channels'],(int)$a['bits'],sf_clean_text($a['codec'],120),$title,'','','','',sf_media_json($a['technical']),sf_media_json([]),$adminId?:null,$now,$now]);$id=(int)sf_db()->lastInsertId();$asset=sf_media_asset($id)?:[];$variants=sf_media_generate_variants($asset);if($variants){sf_db()->prepare('UPDATE media_assets SET variants_json=?,updated_at=? WHERE id=?')->execute([sf_media_json($variants),gmdate('c'),$id]);$asset=sf_media_asset($id)?:$asset;}return $asset;}catch(Throwable $e){@unlink($abs);throw $e;}
}
function sf_media_links(string $entityType,string $entityId): array {
    sf_media_ensure_schema();$q=sf_db()->prepare('SELECT l.*,a.uuid,a.category,a.mime_type,a.extension,a.original_name,a.size_bytes,a.width,a.height,a.duration_seconds,a.bitrate_bps,a.sample_rate_hz,a.channels,a.bits_per_sample,a.codec,a.title,a.caption,a.alt_text,a.credit,a.copyright_text,a.technical_json,a.variants_json FROM media_links l JOIN media_assets a ON a.id=l.asset_id WHERE l.entity_type=? AND l.entity_id=? ORDER BY l.role,l.sort_order,l.id');$q->execute([$entityType,$entityId]);$rows=$q->fetchAll();foreach($rows as &$r){$r['technical']=sf_media_decode($r['technical_json']??'',[]);$r['variants']=sf_media_decode($r['variants_json']??'',[]);$r['link']=sf_media_decode($r['link_json']??'',[]);}unset($r);return $rows;
}
function sf_media_attach(int $assetId,string $entityType,string $entityId,string $role,array $opts=[]): array {
    sf_media_ensure_schema();$asset=sf_media_asset($assetId);if(!$asset)throw new InvalidArgumentException('Media asset not found.');$allowedEntities=['track','release','show','campaign','site','store','member_content'];if(!in_array($entityType,$allowedEntities,true))throw new InvalidArgumentException('Unsupported media entity.');$entityId=sf_clean_text($entityId,160);$role=sf_clean_text($role,60);if($entityId===''||$role==='')throw new InvalidArgumentException('Media entity and role are required.');$now=gmdate('c');$q=sf_db()->prepare('SELECT COALESCE(MAX(sort_order),-1)+1 FROM media_links WHERE entity_type=? AND entity_id=? AND role=?');$q->execute([$entityType,$entityId,$role]);$sort=(int)$q->fetchColumn();
    try{$q=sf_db()->prepare('INSERT INTO media_links(asset_id,entity_type,entity_id,role,sort_order,featured,public_visible,download_allowed,link_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$assetId,$entityType,$entityId,$role,$sort,!empty($opts['featured'])?1:0,!empty($opts['public_visible'])?1:0,!empty($opts['download_allowed'])?1:0,sf_media_json((array)($opts['link']??[])),$now,$now]);}catch(PDOException $e){if(!in_array((string)$e->getCode(),['23000','19'],true))throw $e;}
    return sf_media_links($entityType,$entityId);
}
function sf_media_detach(int $linkId): bool {$q=sf_db()->prepare('DELETE FROM media_links WHERE id=?');$q->execute([$linkId]);return $q->rowCount()>0;}
function sf_media_update_asset(int $id,array $p): array {$allowed=['title'=>255,'caption'=>4000,'alt_text'=>500,'credit'=>255,'copyright_text'=>500];$sets=[];$args=[];foreach($allowed as $k=>$max)if(array_key_exists($k,$p)){$sets[]="$k=?";$args[]=sf_clean_text($p[$k],$max);}if($sets){$sets[]='updated_at=?';$args[]=gmdate('c');$args[]=$id;sf_db()->prepare('UPDATE media_assets SET '.implode(',',$sets).' WHERE id=?')->execute($args);}return sf_media_asset($id)?:[];}
function sf_media_update_link(int $id,array $p): void {$sets=[];$args=[];foreach(['featured','public_visible','download_allowed'] as $k)if(array_key_exists($k,$p)){$sets[]="$k=?";$args[]=!empty($p[$k])?1:0;}if(array_key_exists('role',$p)){$sets[]='role=?';$args[]=sf_clean_text($p['role'],60);}if(array_key_exists('sort_order',$p)){$sets[]='sort_order=?';$args[]=(int)$p['sort_order'];}if(!$sets)return;$sets[]='updated_at=?';$args[]=gmdate('c');$args[]=$id;sf_db()->prepare('UPDATE media_links SET '.implode(',',$sets).' WHERE id=?')->execute($args);}
function sf_media_delete_asset(int $id): bool {$asset=sf_media_asset($id);if(!$asset)return false;$q=sf_db()->prepare('SELECT COUNT(*) FROM media_links WHERE asset_id=?');$q->execute([$id]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Detach this asset everywhere before deleting it.');$paths=[(string)$asset['stored_path']];foreach((array)$asset['variants'] as $v)if(!empty($v['path']))$paths[]=(string)$v['path'];$q=sf_db()->prepare('DELETE FROM media_assets WHERE id=?');$q->execute([$id]);if($q->rowCount())foreach($paths as $p){$abs=realpath(SF_ROOT.'/'.ltrim($p,'/'));$root=realpath(SF_ROOT.'/storage/media');if($abs&&$root&&str_starts_with($abs,$root.DIRECTORY_SEPARATOR))@unlink($abs);}return $q->rowCount()>0;}
function sf_media_list(string $category='',string $q='',int $limit=300): array {sf_media_ensure_schema();$where=['1=1'];$args=[];if($category!==''){$where[]='category=?';$args[]=$category;}if($q!==''){$where[]='(title LIKE ? OR original_name LIKE ? OR caption LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);}$sql='SELECT a.*,(SELECT COUNT(*) FROM media_links l WHERE l.asset_id=a.id) link_count FROM media_assets a WHERE '.implode(' AND ',$where).' ORDER BY a.id DESC LIMIT '.max(1,min(1000,$limit));$st=sf_db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();foreach($rows as &$r){$r['technical']=sf_media_decode($r['technical_json']??'',[]);$r['variants']=sf_media_decode($r['variants_json']??'',[]);}unset($r);return $rows;}
function sf_media_public_links(string $entityType,string $entityId): array {
    $rows=sf_media_links($entityType,$entityId);$out=[];
    foreach($rows as $r)if(!empty($r['public_visible']))$out[]=[
        'uuid'=>(string)$r['uuid'],'category'=>(string)$r['category'],'role'=>(string)$r['role'],'title'=>(string)$r['title'],'caption'=>(string)$r['caption'],'alt_text'=>(string)$r['alt_text'],'credit'=>(string)$r['credit'],'copyright'=>(string)$r['copyright_text'],'featured'=>!empty($r['featured']),'download_allowed'=>!empty($r['download_allowed']),'duration'=>(float)$r['duration_seconds'],'width'=>(int)$r['width'],'height'=>(int)$r['height'],'url'=>'api/media.php?id='.rawurlencode((string)$r['uuid']),'thumb_url'=>!empty($r['variants']['thumb'])?'api/media.php?id='.rawurlencode((string)$r['uuid']).'&variant=thumb':'api/media.php?id='.rawurlencode((string)$r['uuid']),'download_url'=>!empty($r['download_allowed'])?'api/media.php?id='.rawurlencode((string)$r['uuid']).'&download=1':''
    ];
    return $out;
